const tools={adr:['ADR exemption auditor','adr_exemption_auditor.html'],cmr:['CMR waybill issuer','cmr_waybill_issuer.html'],dgr:['DGR acceptance hub','dgr_acceptance_hub.html']};
const $=s=>document.querySelector(s);let current='overview';
function navigate(page){if(!tools[page]&&!['overview','guide'].includes(page))page='overview';current=page;document.querySelectorAll('.page').forEach(el=>el.hidden=true);$('#breadcrumb').textContent=tools[page]?.[0]||(page==='guide'?'How to use this app':'Overview');document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.page===page);if(b.dataset.page===page)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});if(tools[page]){$('#tool').hidden=false;$('#tool-title').textContent=tools[page][0];let frame=$('#frame-'+page);if(!frame){frame=document.createElement('iframe');frame.id='frame-'+page;frame.title=tools[page][0];frame.src=tools[page][1];$('#frames').append(frame)}document.querySelectorAll('iframe').forEach(f=>f.hidden=f!==frame)}else $('#'+page).hidden=false;document.body.classList.remove('nav-open');$('#menu').setAttribute('aria-expanded','false');window.scrollTo(0,0)}
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>{location.hash=b.dataset.page}));window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));navigate(location.hash.slice(1)||'overview');
$('#menu').onclick=()=>{const open=document.body.classList.toggle('nav-open');$('#menu').setAttribute('aria-expanded',String(open))};$('#scrim').onclick=()=>{document.body.classList.remove('nav-open');$('#menu').setAttribute('aria-expanded','false')};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#scrim').click()}});$('#print').onclick=()=>{const f=$('#frame-'+current);if(f){try{f.contentWindow.focus();f.contentWindow.print()}catch{alert('For downloaded offline files, use the Print / Export button inside the document tool below.')}}};
function tick(){const now=new Date();$('#time').textContent=now.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false});$('#date').textContent=now.toLocaleDateString([],{weekday:'short',day:'numeric',month:'long',year:'numeric'})}tick();setInterval(tick,1000);
const read=k=>{try{return JSON.parse(localStorage.getItem(k))}catch{return null}};const save=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch{}};
let weather=read('cargodesk-weather'),city=read('cargodesk-city')||'Berlin';
function connection(){$('#connection').textContent=navigator.onLine?'Local tools · online':'Local tools · offline'}connection();window.addEventListener('online',()=>{connection();refresh(city)});window.addEventListener('offline',()=>{connection();renderWeather(true)});
function weatherLabel(code){if(code===0)return ['☀','Clear'];if(code<=3)return ['☁','Cloudy'];if(code<=48)return ['≋','Fog'];if(code<=67)return ['☂','Rain'];if(code<=77)return ['❄','Snow'];if(code<=82)return ['☂','Showers'];if(code<=86)return ['❄','Snow showers'];return ['ϟ','Thunderstorms']}
function renderWeather(stale=false){$('#city-button').textContent=city+' · Change city';if(!weather){$('#weather-value').textContent='Weather unavailable';$('#weather-status').textContent='Internet needed to refresh';return}const [icon,label]=weatherLabel(weather.code);$('#weather-icon').textContent=icon;$('#weather-value').textContent=Math.round(weather.temp)+'°C · '+label;$('#weather-status').textContent=(stale?'Saved · ':'Updated · ')+new Date(weather.saved).toLocaleString([],{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})}
async function getJSON(url){const response=await fetch(url,{signal:AbortSignal.timeout(12000)});if(!response.ok)throw Error('Weather service unavailable');return response.json()}
async function refresh(name){if(!navigator.onLine){renderWeather(true);return false}try{const geo=await getJSON('https://geocoding-api.open-meteo.com/v1/search?name='+encodeURIComponent(name)+'&count=1&language=en&format=json');if(!geo.results?.length)throw Error('City not found. Try a nearby larger city.');const place=geo.results[0];const data=await getJSON('https://api.open-meteo.com/v1/forecast?latitude='+place.latitude+'&longitude='+place.longitude+'&current=temperature_2m,weather_code');weather={temp:data.current.temperature_2m,code:data.current.weather_code,saved:Date.now()};city=place.name;save('cargodesk-city',city);save('cargodesk-weather',weather);renderWeather();return true}catch(e){renderWeather(true);$('#city-error').textContent=e.message||'Unable to refresh. Please try again.';return false}}
renderWeather(true);refresh(city);setInterval(()=>refresh(city),1800000);$('#city-button').onclick=()=>{$('#city').value=city;$('#city-error').textContent='Weather provided by Open-Meteo.';$('#city-dialog').showModal()};$('#cancel-city').onclick=()=>$('#city-dialog').close();$('#city-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;$('#city-error').textContent='Looking up weather…';if(!navigator.onLine)$('#city-error').textContent='Connect to the internet to change weather location.';else if(await refresh($('#city').value.trim()))$('#city-dialog').close();button.disabled=false};
if('serviceWorker' in navigator&&/^https?:$/.test(location.protocol))navigator.serviceWorker.register('./sw.js').catch(()=>{});
